// BFF层示例（Express）
const express = require('express');
const app = express();

// 聚合多个后端服务
app.get('/api/dashboard', async (req, res) => {
  const [user, orders, notifications] = await Promise.all([
    fetch('http://user-service/api/user/' + req.userId),
    fetch('http://order-service/api/orders?userId=' + req.userId),
    fetch('http://notification-service/api/notifications?userId=' + req.userId)
  ]);

  res.json({
    user: await user.json(),
    orders: await orders.json(),
    notifications: await notifications.json()
  });
});

// GraphQL示例
const { ApolloServer, gql } = require('apollo-server');

const typeDefs = gql`
  type User {
    id: ID!
    name: String!
    email: String!
    posts: [Post!]
  }

  type Post {
    id: ID!
    title: String!
    content: String!
    author: User!
  }

  type Query {
    user(id: ID!): User
    posts(limit: Int): [Post!]
  }
`;

const resolvers = {
  Query: {
    user: (_, { id }) => fetchUser(id),
    posts: (_, { limit }) => fetchPosts(limit)
  },
  User: {
    posts: (user) => fetchPostsByUser(user.id)
  },
  Post: {
    author: (post) => fetchUser(post.authorId)
  }
};

const server = new ApolloServer({ typeDefs, resolvers });
server.listen().then(({ url }) => console.log(`Server at ${url}`));

